#include <stdio.h>
#include <string.h>

int before(const char *a, const char *b) {
    size_t la = strlen(a), lb = strlen(b);
    if (la != lb) {
        return la < lb;
    }
    return strcmp(a, b) < 0;
}

int main(void) {
    int n;
    scanf("%d", &n);
    char words[50][21];
    const char *order[50];
    for (int i = 0; i < n; i++) {
        scanf("%20s", words[i]);
        order[i] = words[i];
    }
    for (int i = 1; i < n; i++) {
        const char *current = order[i];
        int j = i - 1;
        while (j >= 0 && before(current, order[j])) {
            order[j + 1] = order[j];
            j--;
        }
        order[j + 1] = current;
    }
    for (int i = 0; i < n; i++) {
        printf("%s\n", order[i]);
    }
    return 0;
}

