#include <stdio.h>
#include <stdlib.h>

int read_array(int **out, int *length) {
    int n;
    if (scanf("%d", &n) != 1 || n < 0 || n > 100000) {
        return -1;
    }
    if (n == 0) {
        *out = NULL;
        *length = 0;
        return 0;
    }
    int *block = malloc((size_t)n * sizeof *block);
    if (block == NULL) {
        return -1;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &block[i]) != 1) {
            free(block);
            return -1;
        }
    }
    *out = block;
    *length = n;
    return 0;
}

int main(void) {
    int *a = NULL;
    int n = 0;
    if (read_array(&a, &n) != 0) {
        printf("error\n");
        return 0;
    }
    if (n == 0) {
        printf("empty\n");
    } else {
        long long sum = 0;
        int max = a[0];
        for (int i = 0; i < n; i++) {
            sum += a[i];
            if (a[i] > max) {
                max = a[i];
            }
        }
        printf("sum=%lld max=%d\n", sum, max);
    }
    free(a);
    return 0;
}

